import json,pathlib
P=pathlib.Path(__file__).resolve().parents[1]/'app/src/main/assets'
patterns=[]
def add(id,label,group,look,key,trap,report):patterns.append(dict(id=id,label=label,group=group,look=look,key=key,trap=trap,report=report))
add('bpe','Фоновое усиление · BPE','Фон и доброкачественные', 'Количество фиброгландулярной ткани (FGT) оценивают отдельно от её контрастирования. BPE: минимальное, слабое, умеренное, выраженное; дополнительно — симметрия.', 'BPE преимущественно оценивают на первой постконтрастной серии. Минимальное включает отсутствие усиления. Сопоставить фон, гормональный статус и предыдущие исследования.', 'Асимметрия не означает рак автоматически, но требует поиска локальной причины. Нельзя списывать новое сегментарное или очаговое подозрительное усиление на BPE без анализа. Планирование по циклу не должно задерживать обследование подозрительной находки.', 'FGT [A–D]. BPE [минимальное / слабое / умеренное / выраженное], [симметричное / асимметричное]. Локальные находки [ ]. Ограничения оценки [ ].')
add('cyst','Киста / белковое содержимое','Фон и доброкачественные', 'Чётко отграниченное жидкостное образование; обычно T2 высокое, T1 низкое. При белке / крови T1 может быть высоким, T2 — сниженным.', 'Проверить исходную T1 и субтракцию: яркий T1-сигнал не равен накоплению контраста. Тонкое гладкое перикистозное усиление возможно у доброкачественной кисты.', 'Утолщённая неровная стенка, пристеночный усиливающийся компонент или иной подозрительный участок требуют отдельной оценки. Один признак «кольцевого усиления» не отличает кисту, абсцесс и опухоль.', 'В [железе, часы, расстояние] киста [ ] мм, содержимое [ ], стенка [ ], усиливающийся солидный компонент [ ]. При типичной доброкачественной картине — BI-RADS 2.')
add('fibro','Фиброаденомоподобный узел','Фон и доброкачественные', 'Овальный, отграниченный узел с однородным усилением или тёмными внутренними перегородками; T2 может быть высоким. Старые фиброзные узлы нередко T2-низкие.', 'Оценить форму, весь контур, внутренний рисунок, T2 и динамику размеров. Типичный вид поддерживает доброкачественность; при доказанной / устойчивой доброкачественной находке возможна категория 2.', 'T2-высокий сигнал, округлость и washout по отдельности не определяют природу. Новый / растущий / неоднородный узел требует оценки; МРТ не всегда различает фиброаденому и филлоидную опухоль. Категория 3 — только при обоснованном риске ≤2%.', 'В [локализации] узел [размеры], [форма, контур, T2, усиление, динамика]. Картина [типичная доброкачественная / вероятно доброкачественная / подозрительная]. BI-RADS [ ], рекомендация [ ].')
add('fat','Жировой некроз / липидный компонент','Фон и доброкачественные', 'Искать макроскопический жир: T1-сигнал как подкожный жир с подавлением на FS. Возможны масляная киста, тонкое кольцо, послеоперационная деформация.', 'Сопоставить T1 без FS, жироподавление, субтракцию, операцию / травму и маммографию. Для гамартомы характерна смесь жира и железистой ткани в отграниченной зоне.', 'Жировой некроз иногда усиливается и имитирует рак. При сомнительном солидном компоненте или несоответствии анамнезу не считать весь очаг доброкачественным по небольшому включению жира.', 'В [ ] участок [ ] мм с макроскопическим жиром и [морфология], соответствующий [жировому некрозу / гамартоме] при согласованной картине. Подозрительный усиливающийся компонент [ ]. BI-RADS [ ].')
add('mass','Подозрительный узел · mass','Подозрительные находки', 'Трёхмерное объёмное образование: оценить форму, контур, внутреннее усиление и T2. Подозрительны неправильная форма, нечёткий / спикулированный контур, неоднородность и толстое периферическое усиление.', 'Морфологию оценивать на исходных ранних постконтрастных изображениях и реконструкциях; размер — в трёх осях. DWI и кинетика дополняют оценку.', 'Ни washout, ни низкий ADC, ни толстое кольцо не являются самостоятельным диагнозом. Некоторые злокачественные узлы бывают отграниченными и T2-высокими. BI-RADS 4/5 требует морфологической верификации.', 'В [железе, часы, расстояние от соска, глубина] узловое образование [3 размера] мм, [форма], контуры [ ], T2 [ ], усиление [ ], кинетика [ ], DWI/ADC [ ]. BI-RADS [4A/4B/4C/5]. Рекомендована биопсия под контролем метода, уверенно визуализирующего находку.')
add('linear','Линейное NME','Подозрительные находки', 'Усиление без объёмного узла, выстроенное в линию или ветвящуюся линию. Описать внутренний рисунок и протяжённость, связь с соском.', 'Отличить протоковый паттерн от сосуда по исходным срезам и последовательному ходу. Фокальное NME не должно следовать линейному / сегментарному распределению.', 'Отсутствие узла и доброкачественный тип кривой не исключают DCIS или инвазивный компонент. УЗИ и маммография ищут коррелят; при MRI-only подозрительной находке нужна МР-навигация для биопсии.', 'Линейное [ветвящееся] NME в [ ], протяжённость [ ] мм, внутренний рисунок [ ], расстояние от соска [ ]. Коррелят на других методах [ ]. BI-RADS [ ].')
add('segment','Сегментарное NME','Подозрительные находки', 'Клиновидное / конусовидное распределение с вершиной к соску, предполагающее проток и его ветви; усиление отличается от фонового BPE.', 'Указать полный размах усиления, передний и задний край, отношение к соску. Описать однородный, неоднородный, clumped или clustered-ring рисунок.', 'DCIS часто проявляется NME, но паттерн не устанавливает гистологию и не доказывает отсутствие инвазии. Не присваивать категорию 3 только из-за persistent-кинетики.', 'Сегментарное NME в [железе/секторе], общий размах [ ] мм, рисунок [ ], передняя граница [ ] см от соска. BI-RADS [4/5 по совокупности]. Биопсия [метод].')
add('rings','Clumped / clustered-ring NME','Подозрительные находки', 'Clumped: скопления контрастирующейся ткани разного размера. Clustered-ring: группа мелких колец усиления, связанных с протоковым распределением.', 'Внутренний рисунок описывают отдельно от распределения: например, сегментарное NME с clustered-ring усилением. На схеме показан clustered-ring-паттерн; clumped означает скопления усиления, а не кольца.', 'Не путать множество мелких колец NME с единым толстым периферическим усилением узла. Выраженный BPE и движение могут мешать; подозрительную морфологию не отменяет кинетика.', 'NME [распределение], внутреннее усиление [clumped / clustered-ring], протяжённость [ ] мм. BI-RADS [ ]; рекомендована морфологическая верификация.')
add('duct','T1-яркий проток / папиллярный очаг','Протоки и имитаторы', 'Высокий сигнал протока до контраста может соответствовать белковому / геморрагическому содержимому. Усиливающийся внутрипротоковый узел оценивается отдельно.', 'Субтракция с контролем движения помогает отличить содержимое от усиливающейся ткани. Указать проток, ретроареолярную локализацию, узел и выделения из соска.', 'Папиллому, DCIS и другой солидный внутрипротоковый процесс нельзя уверенно разделить только по МРТ. Отрицательная МРТ не закрывает клиническую оценку патологических выделений.', 'В [ ] проток с T1-гиперинтенсивным содержимым [ ], истинное усиление [ ]. Внутрипротоковый узел [размеры, усиление]. BI-RADS [ ]; корреляция с прицельным УЗИ / маммографией и клиникой.')
add('nodes','Лимфоузлы','Распространённость и контроль', 'Оценить внутримаммарные, подмышечные и внутренние грудные узлы: форму, кору, жировые ворота, симметрию и динамику.', 'Асимметричная / фокально утолщённая кора, потеря ворот, округление или рост требуют внимания. УЗИ с возможной пункцией / core-биопсией уточняет подозрительный доступный узел.', 'Один размер не устанавливает метастаз. Реактивные изменения, вакцинация и силикон могут имитировать поражение. Нормальная МР-морфология не исключает микрометастазы; универсальный порог коры для МРТ здесь не используется.', 'Лимфоузлы [группа/сторона]: [морфология, размеры, кора, ворота, динамика]. [Подозрительные / вероятно реактивные] признаки. При необходимости — прицельное УЗИ и верификация.')
add('infection','Абсцесс / воспалительный процесс','Протоки и имитаторы', 'Жидкостная полость с периферическим усилением, окружающим отёком и возможным центральным ограничением диффузии; сопоставить боль, лихорадку, лактацию и вмешательства.', 'Проверить кожу, подкожную клетчатку, протоки, возможный свищ, усиливающуюся ткань и лимфоузлы. Прицельное УЗИ оценивает жидкость и возможность аспирации.', 'Низкий ADC встречается в гное. Воспалительный рак может перекрываться с маститом; отсутствие ожидаемого клинического улучшения и стойкое подозрение требуют верификации. МРТ сама по себе не устанавливает воспалительный рак.', 'В [ ] жидкостное образование [ ] мм, стенка [ ], окружающие изменения [ ], DWI [ ]. Картина возможного абсцесса при соответствующей клинике. Солидный компонент [ ]. Рекомендована [УЗ-оценка / аспирация / биопсия по задаче].')
add('postop','После операции / подозрение на рецидив','Распространённость и контроль', 'Серома / гематома, рубец, жировой некроз и кожно-трабекулярные изменения оцениваются с учётом операции, облучения и сроков.', 'Тонкий гладкий край жидкостного скопления может быть доброкачественным. Подозрительны новый узловой компонент, увеличение и несоответствие ожидаемой динамике.', 'Послеоперационное усиление может сохраняться; универсальной безопасной временной границы нет. Ранняя МРТ имеет ограничения, а отсутствие усиления не исключает микроскопическую остаточную опухоль.', 'В зоне [операции] [серома/рубец/жировой некроз], динамика относительно [дата] [ ]. Подозрительный узловой / NME-компонент [ ]. BI-RADS [ ], рекомендация [ ].')
add('extent','Известный рак · распространённость','Распространённость и контроль', 'Описать индексную опухоль, протяжённость соседнего усиления, отдельные очаги, контралатеральную железу, сосок, кожу, грудные мышцы, грудную стенку и лимфоузлы.', 'Привязать индексный рак к клипсе / месту биопсии. Дополнительный отдельный участок, меняющий операцию, обычно требует подтверждения. Участие грудной мышцы и истинной грудной стенки разделять.', 'Сам контакт, отсутствие жировой прослойки или отёк не равны инвазии. Вовлечение большой грудной мышцы само по себе не означает T4a. BI-RADS — категория оценки, а не стадия TNM.', 'Биопсией подтверждённый рак [локализация], размеры [ ], общий размах [ ]. Дополнительные находки [ ], вовлечение соска/кожи/мышцы/грудной стенки [раздельно]. Узлы [ ]. BI-RADS [6 для известного рака; дополнительные находки отдельно].')
add('response','После неоадъювантной терапии','Распространённость и контроль', 'Сравнить с исходной МРТ до лечения: размер и распределение остаточного усиления, фрагментацию, клипсу, кожу и узлы; указать даты и этап терапии.', 'Измерять остаточную усиливающуюся ткань и её общий размах, а не только полость / рубец. Важны одинаковые протокол и временные фазы.', 'Отсутствие остаточного усиления не доказывает патологический полный ответ (pCR). Фоновое усиление и сосудистые эффекты терапии влияют на видимость. При незавершённом окончательном лечении подтверждённый рак остаётся категорией 6.', 'После [режим/этап] относительно [дата] [уменьшение/отсутствие/сохранение] усиления в зоне клипсы; остаточная находка [ ], общий размах [ ], узлы [ ]. МР-ответ не является подтверждением pCR.')
implants=[]
def imp(id,label,look,key,trap):implants.append(dict(id=id,label=label,group='Импланты',look=look,key=key,trap=trap,report='Имплант [сторона, положение, материал]. [Описать оболочку, капсулу, линии, свободный силикон, жидкость, образования и узлы]. Заключение о целостности [ ]; клиническая рекомендация [ ].'))
imp('folds','Норма / радиальные складки','Оболочка и окружающая фиброзная капсула — разные структуры. Небольшой объём периимплантной жидкости и радиальные складки возможны в норме.','Проверить связь складки с периферией на соседних срезах и нескольких плоскостях. Описать препекторальное / ретропекторальное положение, материал и тип просвета.','Одна низкосигнальная линия не означает разрыв. Складки и архитектуру многопросветного импланта оценивать с учётом его модели.')
imp('intra','Интракапсулярный разрыв','Разрыв эластомерной оболочки при удержании силикона фиброзной капсулой. Возможны subcapsular-line, keyhole и linguine-признаки.','На silicone-only / water-suppressed сериях оценить гель и сложенную оболочку; при коллапсе видны множественные извилистые тёмные линии внутри силикона.','Признаки зависят от конструкции и когезивности геля; отсутствие классического linguine не исключает разрыв. Подтверждать в нескольких плоскостях, отличать складки.')
imp('extra','Экстракапсулярный силикон','Силикон за пределами фиброзной капсулы в ткани молочной железы; силикон-специфические серии подтверждают его состав.','Искать текущий и ранее удалённый имплант, распространённость силикона, гранулёмы и лимфоузлы. Сопоставить с предыдущими вмешательствами.','Силикон в лимфоузле сам по себе не доказывает текущий экстракапсулярный разрыв: возможны старый разрыв и silicone bleed при интактном импланте.')
imp('seroma','Поздняя серома / капсулярная масса','Новый значимый поздний выпот, капсулярное образование, нарастающее увеличение груди или лимфаденопатия требуют отдельной оценки.','УЗИ — для жидкости / доступной массы; при подозрении на BIA-ALCL — аспирация с цитологией и профильными тестами CD30 / ALK по клиническому маршруту. Контрастная МРТ помогает оценить массу и распространённость.','Малая стабильная жидкость может быть нормальной. Ни МРТ, ни факт наличия жидкости не диагностируют BIA-ALCL. Дифференциал включает инфекцию, разрыв и другие капсулярные опухоли.')
categories=[
 ['0','Неполная оценка','Риск не задаётся','Указать, чего не хватает: дополнительной визуализации ИЛИ предыдущих исследований. На полноценной МРТ использовать обоснованно; необходимость биопсии сама по себе не причина категории 0.'],
 ['1','Отрицательный результат','Практически 0%','Патологических находок нет. Скрининг — по индивидуальному риску и применимым рекомендациям; МРТ не заменяет показанную маммографию.'],
 ['2','Доброкачественная находка','Практически 0%','Убедительная доброкачественная морфология / согласованная история: например, типичная киста. Обычный скрининг по риску.'],
 ['3','Вероятно доброкачественная','≤2%','Только обоснованный низкорисковый паттерн после полноценной оценки. Обычно контроль через 6 месяцев с дальнейшим наблюдением на 12 и 24 месяцах при стабильности. Новый / растущий очаг и предоперационная оценка известного рака требуют особой осторожности.'],
 ['4','Подозрительная находка','>2% и <95%','Рекомендована морфологическая верификация. В v2025 для МРТ допустимы необязательные подкатегории 4A–4C; их нельзя получать из одного признака или калькулятора кинетики.'],
 ['4A','Низкая степень подозрения','>2% и ≤10%','Биопсия. Низкая степень подозрения не означает наблюдение вместо верификации.'],
 ['4B','Умеренная степень подозрения','>10% и ≤50%','Биопсия; требуется радиолого-патологическое сопоставление результата.'],
 ['4C','Высокая степень подозрения','>50% и <95%','Биопсия; при доброкачественном ответе тщательно оценить соответствие изображениям.'],
 ['5','Высокая вероятность рака','≥95%','Биопсия / соответствующая клиническая маршрутизация. Доброкачественная гистология при явно подозрительной картине требует проверки дискордантности.'],
 ['6','Известная злокачественность','Подтверждена биопсией','До окончательного лечения, включая оценку на фоне неоадъювантной терапии. Дополнительный отдельный подозрительный очаг не становится категорией 6 автоматически; исключение ACF требует всех условий ниже.']]
lexicon=[
 ['FGT и BPE','FGT A–D: от почти жировой до выраженной железистой ткани. BPE: минимальное (включая отсутствие), слабое, умеренное, выраженное; симметричное / асимметричное. Это разные характеристики.'],
 ['Mass · форма','Овальная, дольчатая (lobulated), округлая, неправильная. Дольчатая форма в v2025 — отдельный вариант; слово не обозначает дольковый гистологический тип рака.'],
 ['Mass · контур','Чётко отграниченный или неотграниченный: нечёткий (indistinct) / спикулированный. «Неправильная» относится к форме, а не к отдельному контуру v2025.'],
 ['Mass · усиление и T2','Однородное, неоднородное, с тёмными внутренними перегородками, толстое периферическое. T2: равномерно высокий (сопоставимый с ярким лимфоузлом) или неравномерно / недостаточно высокий. T2 не определяет категорию сам по себе.'],
 ['NME · распределение','Диффузное; регионарное; фокальное; линейное; сегментарное. Фокальное занимает ограниченную область без протоковой геометрии; сегментарное ориентировано вершиной к соску. Multiple regions удалён как отдельный дескриптор v2025.'],
 ['NME · внутренний рисунок','Однородный; неоднородный; clumped (глыбчатый / сгруппированный); clustered-ring (сгруппированные мелкие кольца). Рисунок и распределение описывать раздельно.'],
 ['Малые находки','Focus больше не отдельный термин v2025. Малую контрастирующуюся находку описывают по доступной морфологии как небольшой mass или фокальное NME. При недостаточном разрешении указать ограничение; не выдумывать контур.'],
 ['Кинетика','Ранняя фаза около 60–120 с: прирост <50%, 50–100%, >100%. Поздняя фаза относительно ранней: рост >10%, изменение в пределах ±10%, снижение >10%. Параметры зависят от протокола; морфология и клиника обязательны.'],
 ['Локализация','Сторона; часы (целое число) и/или сектор; передняя / средняя / задняя треть; расстояние от основания соска до центра находки в см, при необходимости до кожи / грудной стенки. Размеры по трём осям; для NME — полный размах.'],
 ['Сопутствующие признаки','Втяжение / вовлечение соска, втяжение / утолщение / вовлечение кожи, вовлечение грудной мышцы и отдельно грудной стенки, перитуморальный отёк. Контакт и отёк не равны доказанной инвазии.'],
 ['DWI / ADC','Оценить качество, b-значения и соответствие находке на DCE. Высокий DWI без сниженного ADC может быть T2 shine-through. ROI ставить в жизнеспособную ткань, избегая некроза, жира, артефактов; для малых очагов и NME ограничения особенно значимы. Универсального порога ADC для BI-RADS нет.']]
scan=[
 ['Основа','Специализированная двусторонняя катушка, положение на животе','Обе железы от подмышечных хвостов до субмаммарных складок; соски, ретроареолярные зоны, кожа и задние отделы. Складки / компрессию тканей и движение минимизировать.'],
 ['Основа','T2 / bright-fluid до контраста','AX T2 FS или качественная эквивалентная серия; жидкость, отёк, T2-характеристика узла. При вопросе о жире — T1 без FS или корректное Dixon-разделение.'],
 ['Основа','3D T1 DCE до и после контраста','Одинаковые геометрия и параметры до / после. Ранняя и отсроченная фазы; исходные изображения + проверенная субтракция, MIP и MPR. MIP не заменяет просмотр срезов.'],
 ['Аккредитационный минимум ACR2025','Срез ≤3 мм; без промежутка; пиксель ≤1×1 мм','Размер пикселя относится к полученным, не интерполированным данным. Первая постконтрастная серия завершена не позднее 4 минут после окончания инъекции (без учёта промывания). Это критерии аккредитации, а не оптимальная временная цель динамики.'],
 ['Клиническая динамика','Ранняя оценка в окне около 60–120 с; дальнейшие фазы','Предпочитать высокое пространственное разрешение и воспроизводимую временную выборку. В практике часто стремятся к срезу около 1 мм; параметры адаптировать к SNR / катушке / задаче. Не называть позднюю первую фазу полноценной ранней кинетикой.'],
 ['Рекомендуемое дополнение','DWI до контраста + ADC','EUSOBI2020: низкое b 0–50 и высокое b 800 с/мм²; физическое разрешение ≤2×2 мм, срез ≤4 мм, подавление жира. Более высокие b — дополнительный вариант для видимости, ADC зависит от b и техники.'],
 ['Отдельная задача','Целостность силиконового импланта','Silicone-only / water-suppressed и water-only / silicone-suppressed серии в нужных плоскостях, T2. Для одной только целостности контраст обычно не нужен. При подозрении на опухоль или капсулярную массу нужен соответствующий DCE-протокол.'],
 ['По показаниям','Ultrafast / сокращённый протокол / уточняющие серии','Сокращённый протокол применять по валидированному маршруту; он не автоматически достаточен для распространённости, сложного импланта или оценки лечения. Название GE-серии и ускорение зависят от доступных лицензий и катушки.'],
 ['Перед завершением','Качество и возможность дальнейшей верификации','Проверить введение контраста, жироподавление, движение, субтракцию и покрытие. MRI-only подозрительная находка требует доступного маршрута МР-биопсии; отрицательное second-look УЗИ не отменяет подозрительную МР-морфологию.']]
reports=[
 ['Структура полного описания','Показание [скрининг / диагностическая задача / известный рак, этап]. Сравнение [даты]. Техника [катушка, DCE, временные фазы, DWI/b, контраст по локальному протоколу], качество [ ]. FGT [A–D], BPE [уровень, симметрия]. Правая железа [ ]. Левая железа [ ]. Для каждой находки: часы/сектор, глубина, расстояние от соска, размеры, mass/NME, морфология, T2, кинетика, DWI/ADC, динамика. Соски/кожа/грудные мышцы/грудная стенка [ ]. Узлы [ ]. Импланты [ ]. BI-RADS и рекомендация для значимых находок; итоговая оценка [ ].'],
 ['Вероятно доброкачественный узел','[Сторона, часы, расстояние] узел [ ] мм: [форма, контур, T2, рисунок, динамика]. Совокупная картина обоснованно соответствует BI-RADS 3 [указать аргументы и контекст]. Контрольная МРТ через 6 месяцев с дальнейшим наблюдением при стабильности. При росте или изменении морфологии — пересмотр категории.'],
 ['MRI-only подозрительная находка','В [ ] определяется [mass/NME, размеры, морфология], BI-RADS [4A/4B/4C/5]. Рекомендована прицельная корреляция с УЗИ/маммографией для выбора метода биопсии; при отсутствии уверенного коррелята — МР-контролируемая биопсия.'],
 ['Известный рак и отдельный очаг','Подтверждённый биопсией рак [ ], BI-RADS 6. Дополнительная отдельная находка [локализация, расстояние до индексного очага, морфология, размер], BI-RADS [4/5 либо обоснованное применение ACF]. Изменение общего размаха и потенциальное влияние на тактику [ ]. Необходимость отдельной верификации [ ].'],
 ['Технически ограниченное исследование','Оценка ограничена [отсутствием адекватного усиления / движением / артефактом / неполным покрытием]. Необходимы [конкретные дополнительные изображения / предыдущие исследования]. Категория [0 при неполной оценке]; не считать ограниченное исследование отрицательным.']]
sources=[['ACR BI-RADS v2025 · официальный MRI Lexicon Summary','https://edge.sitecorecloud.io/americancoldf5f-acrorgf92a-productioncb02-3650/media/ACR/Files/RADS/BI-RADS/BI-RADS-Summary-Form-MRI.pdf'],['ACR BI-RADS v2025 · официальный перечень изменений','https://edge.sitecorecloud.io/americancoldf5f-acrorgf92a-productioncb02-3650/media/ACR/Files/RADS/BI-RADS/BIRADS-v2025-Whats-New.pdf'],['ACR · параметры Breast MRI, редакция19.03.2025','https://accreditationsupport.acr.org/support/solutions/articles/11000114407-mri-exam-specific-parameters-breast-revised-4-28-22-'],['EUSOBI2020 · консенсус DWI','https://pmc.ncbi.nlm.nih.gov/articles/PMC7033067/'],['ACR2023 · Breast Implant Evaluation','https://acsearch.acr.org/docs/3100728/Narrative/'],['FDA · BIA-ALCL, диагностика поздних периимплантных изменений','https://www.fda.gov/medical-devices/breast-implants/questions-and-answers-about-breast-implant-associated-anaplastic-large-cell-lymphoma-bia-alcl'],['Клинические пояснения к BI-RADS v2025 MRI · 2026','https://pmc.ncbi.nlm.nih.gov/articles/PMC13266119/']]
